document.addEventListener("DOMContentLoaded",function(){const checkboxes=document.querySelectorAll(".ingredient-checkbox"),recipeId=window.ViewRecipeConfig.recipeId;checkboxes.forEach(checkbox=>{const id=checkbox.id;localStorage.getItem(`recipe_${recipeId}_${id}`)==="true"&&(checkbox.checked=!0),checkbox.addEventListener("change",function(){localStorage.setItem(`recipe_${recipeId}_${id}`,this.checked)})})}),window.ViewRecipeConfig&&window.ViewRecipeConfig.isOwner&&(window.openEditModal=function(){document.getElementById("editRecipeModal").style.display="block",document.body.style.overflow="hidden"},window.closeEditModal=function(){document.getElementById("editRecipeModal").style.display="none",document.body.style.overflow="auto"},window.confirmDelete=function(){confirm("Are you sure you want to delete this recipe? This action cannot be undone and will remove the recipe from all collections.")&&document.getElementById("deleteForm").submit()},window.addEventListener("click",function(event){const modal=document.getElementById("editRecipeModal");event.target===modal&&closeEditModal()}),document.addEventListener("keydown",function(event){event.key==="Escape"&&closeEditModal()}));
